<script setup lang="ts">
import {computed,ref,reactive,watch,nextTick,onBeforeUnmount} from 'vue';
import {Button,Dialog,Tabs,useHostContext} from '@openclaw-plugins/control-ui-kit';
import AuditView from './AuditView.vue';
import type {AuditPage} from './audit-model';
import {type ScheduledTask,type TaskRun,syncLabels,date,shortTime,duration,taskState,taskSchedule,planText} from './task-directory-model';
const props=withDefaults(defineProps<{tasks:ScheduledTask[];agentId:string;full?:boolean;available?:boolean;invoke:<T>(action:string,payload:Record<string,unknown>)=>Promise<T>;safe:(v:unknown)=>string;onManage:(id?:string,action?:string)=>void}>(),{available:true,full:false});
const context=useHostContext(),root=ref<HTMLElement>(),scroll=ref<HTMLElement>();
const tasks=computed(()=>props.tasks.filter(t=>!['removed','purged'].includes(t.status??''))),taskId=ref(''),runId=ref(''),tab=ref('records');
const task=computed(()=>tasks.value.find(t=>t.taskId===taskId.value)),run=computed(()=>task.value?.records.find(r=>r.runId===runId.value));
const loaded=reactive(new Map<string,{record?:TaskRun;error?:string;loading?:boolean;epoch?:number}>()),positions=new Map<string,number>();
const focusTaskId=ref('');
const returnFocus=()=>Array.from(root.value?.querySelectorAll<HTMLElement>('[data-task-id]')??[]).find(n=>n.dataset.taskId===focusTaskId.value)??null;
const viewKey=computed(()=>run.value?'run:'+run.value.runId:'task:'+taskId.value+':'+tab.value);
const views=[{id:'records',label:'执行记录'},{id:'settings',label:'任务设置'},{id:'audit',label:'修改日志'}];
let epoch=0,alive=true;
const groupName=(t:ScheduledTask)=>{const key='agent:'+props.agentId+':feishu:group:'+t.chatId,row=context.value.host.sessions.rows?.find(row=>row.key===key);return [row?.label,row?.displayName].find(name=>typeof name==='string'&&name.trim()&&!name.includes(t.chatId??''))?.trim()??'群名称未获取';};
function saveScroll(){if(scroll.value)positions.set(viewKey.value,scroll.value.scrollTop);}
async function restoreScroll(){await nextTick();if(scroll.value)scroll.value.scrollTop=positions.get(viewKey.value)??0;}
async function close(restore=true){const id=taskId.value;epoch++;taskId.value='';runId.value='';tab.value='records';loaded.clear();positions.clear();await nextTick();if(!restore)return;Array.from(root.value?.querySelectorAll<HTMLElement>('[data-task-id]')??[]).find(n=>n.dataset.taskId===id)?.focus({preventScroll:true});}
async function open(id:string){epoch++;loaded.clear();positions.clear();focusTaskId.value=id;taskId.value=id;runId.value='';tab.value='records';await nextTick();scroll.value?.closest('[role=dialog]')?.querySelector<HTMLElement>('.ocp-dialog-close')?.focus();}
async function loadRecord(record:TaskRun,retry=false){if(!alive||!context.value.presented||!context.value.host.connection.canRead||!retry&&loaded.has(record.runId)&&(!loaded.get(record.runId)?.loading||loaded.get(record.runId)?.epoch===epoch))return;const token=epoch,owner=props.agentId;loaded.set(record.runId,{loading:true,epoch:token});try{const result=await props.invoke<TaskRun>('taskRecord',{taskId:record.taskId,runId:record.runId});if(!alive||token!==epoch||owner!==props.agentId)return;if(result.taskId!==record.taskId||result.runId!==record.runId)throw Error('执行记录来源与当前任务不一致');loaded.set(record.runId,{record:result});}catch(e){if(alive&&token===epoch)loaded.set(record.runId,{error:props.safe(e instanceof Error?e.message:e)});}}
async function openRun(record:TaskRun){saveScroll();epoch++;runId.value=record.runId;await restoreScroll();scroll.value?.closest('[role=dialog]')?.querySelector<HTMLElement>('.ocp-dialog-close')?.focus();void loadRecord(record);}
async function back(){saveScroll();epoch++;const previous=runId.value;runId.value='';tab.value='records';await restoreScroll();Array.from(scroll.value?.querySelectorAll<HTMLElement>('[data-run-id]')??[]).find(n=>n.dataset.runId===previous)?.focus({preventScroll:true});}
async function changeTab(value:string){saveScroll();tab.value=value;await restoreScroll();}
const settings=computed<[string,unknown][]>(()=>{const t=task.value;if(!t)return [];const data:[string,unknown][]=[['任务类型',t.type==='scheduled-request'?'群内定时请求':'仓库同步'],['任务来源',t.type==='scheduled-request'?'OpenClaw 原生调度 → Main':'系统任务'],['所属 Agent',props.agentId],['执行范围',t.scope.label],['执行计划',taskSchedule(t)],['时区',t.schedule?.timeZone??t.schedule?.tz??'Asia/Shanghai'],['任务状态',taskState(t)]];if(t.type==='scheduled-request')data.push(['投递位置',({source:'原请求位置',group:'群主会话',thread:'原请求话题'} as Record<string,string>)[t.deliveryMode??'source']],['原请求人',t.requester],['来源群',groupName(t)],['群 ID',t.chatId],['OpenClaw 任务 ID',t.jobId],['最近原生调度',t.nativeLastStatus??'尚无记录']);else if(t.jobId)data.push(['OpenClaw 任务 ID',t.jobId]);return data;});
const reasons=computed(()=>run.value?[run.value.reason,...(run.value.failures??[]).map(f=>(f.projectId??'项目')+'：'+f.reason)].filter(Boolean):[]);
const auditInvoke=(action:string,payload:Record<string,unknown>)=>props.invoke<AuditPage>(action,payload);
function manage(t:ScheduledTask,action?:string){props.onManage(t.taskId.replace(/^scheduled-request:/,''),action);}
function manageCurrent(){const current=task.value;if(!current)return;void close(false);manage(current);}
watch(()=>props.tasks,()=>{epoch++;loaded.clear();if(taskId.value&&!task.value){void close();return;}if(runId.value&&!run.value)runId.value='';if(run.value)void loadRecord(run.value);});
watch([()=>props.agentId,()=>context.value.presented,()=>context.value.host.connection.canRead,()=>context.value.host.connection.canWrite],()=>close(),{flush:'sync'});
onBeforeUnmount(()=>{alive=false;epoch++;});
</script>
<template><section ref="root" class="ar-sync-history"><div class="ar-sync-heading"><h3 v-if="!full">定时任务</h3><span class="ar-meta">{{tasks.length}} 个任务</span><Button variant="outline" @click="onManage()">管理定时任务</Button></div><p v-if="!available" class="ar-warning">OpenClaw 联动任务服务暂不可读取，以下列表可能不完整。</p><p v-if="!tasks.length" class="ar-muted">暂无定时任务</p><div :class="full?'ar-task-grid':''"><component :is="full?'article':'div'" v-for="t in tasks" :key="t.taskId" :class="full?'ar-task-card':''"><Button class="ar-scheduled-task ocp:h-auto ocp:whitespace-normal" variant="ghost" :data-task-id="t.taskId" :aria-label="'查看'+t.name" aria-haspopup="dialog" @click="open(t.taskId)"><span class="ar-task-row-top"><strong>{{safe(t.name)}}</strong><span class="ar-sync-badge" :class="t.enabled?'enabled':'paused'">{{taskState(t)}}</span></span><span class="ar-task-row-meta">{{safe((t.type==='scheduled-request'?'OpenClaw 联动 · ':'系统任务 · ')+taskSchedule(t))}}</span><template v-if="t.type==='scheduled-request'"><span class="ar-task-row-meta">{{safe('来源群：'+groupName(t))}}</span><span class="ar-task-row-meta">{{safe('原请求人：'+(t.requester??'未记录'))}}</span></template><span v-else class="ar-task-row-meta">{{safe(t.scope.label)}}</span><span class="ar-task-row-bottom"><span>{{safe('下次计划：'+planText(t))}}</span><span>上次：<span v-if="t.lastRun" class="ar-sync-badge" :class="t.lastRun.status">{{syncLabels[t.lastRun.status]??'未知'}}</span><span v-else class="ar-muted">尚未执行</span></span></span></Button><div v-if="full" class="ar-task-card-actions"><Button variant="ghost" :aria-label="'编辑'+t.name" aria-haspopup="dialog" @click="manage(t)">编辑计划</Button><Button v-for="[action,label] in [[t.enabled?'pause':'resume',t.enabled?'停止':'开始'],['remove','删除']]" :key="action" variant="ghost" :aria-label="label+t.name" aria-haspopup="dialog" :disabled="!context.host.connection.canWrite||(t.status==='removed'&&!(t.type==='repository-sync'&&action==='resume'))" @click="manage(t,action)">{{label}}</Button></div></component></div>
<Dialog size="wide" :open="!!task" :title="run?'执行详情':safe(task?.name)" :return-focus="returnFocus" content-class="ar-task-dialog" @update:open="()=>close()"><template v-if="task"><header class="ar-sync-dialog-header"><nav class="ar-task-breadcrumb" aria-label="定时任务路径"><Button variant="link" @click="close()">定时任务</Button><span>/</span><template v-if="run"><Button variant="link" @click="back">{{safe(task.name)}}</Button><span>/</span><span>{{safe(run.date)}}</span></template><span v-else>{{safe(task.name)}}</span></nav></header><div ref="scroll" class="ar-sync-dialog-body"><template v-if="!run"><p class="ar-sync-task-description">{{safe((task.type==='scheduled-request'?'原群 '+groupName(task)+' · 原请求人 '+(task.requester??'未记录'):task.scope.label)+' · '+taskSchedule(task))}}</p><Button variant="outline" @click="manageCurrent">管理此任务</Button><Tabs :model-value="tab" :items="views" label="任务详情" @update:model-value="changeTab"><template #default><section v-if="tab==='records'" class="ar-task-records"><p class="ar-meta">最近 {{task.records.length}} 次执行</p><p v-if="!task.records.length" class="ar-muted">暂无执行记录。任务首次运行后会显示在这里。</p><div v-else class="ar-sync-list"><div class="ar-sync-columns" aria-hidden="true"><span>执行时间</span><span>结果</span><span>耗时</span><span/></div><Button v-for="record in task.records" :key="record.runId" class="ar-sync-record ocp:h-auto" variant="ghost" :data-run-id="record.runId" :aria-label="'查看 '+record.date+' 执行详情'" :title="safe(record.reason??record.failures?.[0]?.reason??'查看执行详情与日志')" @click="openRun(record)"><span class="ar-sync-record-info"><strong>{{safe(record.date)}}</strong><span class="ar-sync-record-time">{{safe(shortTime(record.startedAt))}}</span></span><span class="ar-sync-badge" :class="record.status">{{syncLabels[record.status]??'未知'}}</span><span class="ar-sync-elapsed">{{duration(record)}}</span><span class="ar-sync-arrow">›</span></Button></div><p v-if="task.hasMore" class="ar-muted">仅展示最近 30 次记录，更早记录保留在对应任务的私有状态中。</p></section><section v-else-if="tab==='settings'" class="ar-task-settings"><dl class="ar-task-config"><template v-for="[label,value] in settings" :key="label"><dt>{{label}}</dt><dd>{{safe(value)}}</dd></template></dl><p class="ar-muted">{{task.type==='scheduled-request'?'在任务列表点击“管理定时任务”可修改计划；原生调度成功或 Main 接纳不代表业务完成。':task.readOnly?'此处只读展示；系统同步计划由部署配置管理。':'在任务列表点击“管理定时任务”管理原生同步计划；当天已尝试的同步不会重跑。'}}</p></section><AuditView v-else :invoke="auditInvoke" :safe="safe" feature="schedules" :target-id="task.taskId.replace(/^scheduled-request:/,'')"/></template></Tabs></template>
<template v-else><div class="ar-sync-overview"><span class="ar-sync-badge" :class="run.status">{{syncLabels[run.status]??'未知'}}</span><span class="ar-meta">{{safe('定时触发 · Agent '+agentId)}}</span></div><dl class="ar-sync-metadata"><div v-for="[label,value] in [['开始时间',date(run.startedAt)],['结束时间',date(run.finishedAt)],['执行耗时',duration(run)]]" :key="label"><dt>{{label}}</dt><dd>{{safe(value)}}</dd></div></dl><section v-if="reasons.length" class="ar-sync-failure"><h3>失败原因</h3><p v-for="(reason,index) in reasons" :key="index">{{safe(reason)}}</p></section><p v-if="run.status==='running'" class="ar-muted">记录尚未结束；进程中断也可能留下此状态。刷新可查看最新记录。</p><section class="ar-sync-events"><div class="ar-sync-heading"><h3>执行日志</h3><span v-if="loaded.get(run.runId)?.record" class="ar-meta">{{loaded.get(run.runId)?.record?.logs?.length??0}} 条</span></div><template v-if="loaded.get(run.runId)?.error"><p class="ar-error">{{loaded.get(run.runId)?.error}}</p><Button variant="outline" @click="loadRecord(run,true)">重试读取日志</Button></template><template v-else-if="loaded.get(run.runId)?.record"><p v-if="!loaded.get(run.runId)?.record?.logs?.length" class="ar-muted">此记录没有详细阶段日志；旧版记录仅保存最终结果。</p><ol class="ar-sync-log" aria-label="同步执行日志"><li v-for="(event,index) in loaded.get(run.runId)?.record?.logs??[]" :key="index" class="ar-sync-event" :class="event.status"><div class="ar-sync-event-top"><time>{{safe(shortTime(event.time))}}</time><strong>{{safe(event.stage??'同步')}}</strong><span class="ar-sync-badge" :class="event.status">{{syncLabels[event.status]??'未知'}}</span></div><p class="ar-sync-event-meta">{{safe([event.projectId?'项目 '+event.projectId:'Agent',event.repository,event.branch?'分支 '+event.branch:null,event.head?'提交 '+event.head.slice(0,12):null].filter(Boolean).join(' / '))}}</p><p v-if="event.reason" class="ar-sync-event-reason">{{safe(event.reason)}}</p></li></ol><p v-if="loaded.get(run.runId)?.record?.logsTruncated" class="ar-warning">阶段日志达到条数或大小上限，后续日志未保存。</p></template><p v-else class="ar-muted">正在读取执行日志…</p></section><Button class="ar-task-back" variant="outline" @click="back">返回执行记录</Button></template></div></template></Dialog></section></template>
